-- ============================================================
-- autumn-data 动态层示例库（PostgreSQL 12+ / H2 MODE=PostgreSQL）
--
-- 与 schema.sql 保持同构：表、列、约束、索引一一对应，只有自增主键改成
-- 标准 SQL 的 GENERATED BY DEFAULT AS IDENTITY。
--
-- 幂等：全部 CREATE TABLE / INDEX 都带 IF NOT EXISTS。
-- ============================================================

CREATE TABLE IF NOT EXISTS demo_customer (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    customer_no VARCHAR(32) NOT NULL,
    name VARCHAR(64) NOT NULL,
    phone VARCHAR(32),
    level INT NOT NULL DEFAULT 1,
    deleted_flag INT NOT NULL DEFAULT 0,
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT uk_demo_customer_no UNIQUE (customer_no)
);

CREATE TABLE IF NOT EXISTS demo_order (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_no VARCHAR(32) NOT NULL,
    customer_id BIGINT NOT NULL,
    amount DECIMAL(14, 2) NOT NULL DEFAULT 0,
    status INT NOT NULL DEFAULT 0,
    remark VARCHAR(128),
    deleted_flag INT NOT NULL DEFAULT 0,
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT uk_demo_order_no UNIQUE (order_no)
);

CREATE TABLE IF NOT EXISTS demo_order_item (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_id BIGINT NOT NULL,
    sku VARCHAR(64) NOT NULL,
    product_name VARCHAR(128),
    quantity INT NOT NULL DEFAULT 1,
    price DECIMAL(12, 2) NOT NULL DEFAULT 0,
    deleted_flag INT NOT NULL DEFAULT 0,
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

-- 普通索引不放进建表脚本（保持和 schema.sql 同构、也避免重复执行时冲突）：
--   CREATE INDEX IF NOT EXISTS idx_demo_order_customer ON demo_order (customer_id);
--   CREATE INDEX IF NOT EXISTS idx_demo_order_status ON demo_order (status);
--   CREATE INDEX IF NOT EXISTS idx_demo_order_item_order ON demo_order_item (order_id);
